from concurrent.futures import ThreadPoolExecutor

import pytest

WORKERS: int = 4
"""Number of threads sum_squares uses; the result must not depend on it."""


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Sum of x*x over every element of xs, squaring in a thread pool.

    Uses WORKERS threads (at least one). The result is the same for every
    worker count, including when WORKERS exceeds len(xs). An empty list
    gives 0. The input list is not modified.
    """
    workers = max(1, WORKERS)
    with ThreadPoolExecutor(max_workers=workers) as ex:
        return sum(ex.map(square, xs))


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_big_ints() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16, 100])
def test_same_at_every_worker_count(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    xs = list(range(-50, 200))
    expected = sum(x * x for x in xs)
    monkeypatch.setattr(f"{__name__}.WORKERS", workers)
    assert sum_squares(xs) == expected


@pytest.mark.parametrize("workers", [1, 2, 8, 64])
def test_workers_exceed_length(
    monkeypatch: pytest.MonkeyPatch, workers: int
) -> None:
    monkeypatch.setattr(f"{__name__}.WORKERS", workers)
    assert sum_squares([2, 3]) == 13
    assert sum_squares([]) == 0


def test_large_input_matches_sequential() -> None:
    xs = [(i * 7919) % 1001 - 500 for i in range(5000)]
    assert sum_squares(xs) == sum(square(x) for x in xs)


def test_input_not_modified() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


def test_uses_thread_pool_executor_api() -> None:
    # Sanity check that the pool type is available for the implementation.
    with ThreadPoolExecutor(max_workers=2) as ex:
        assert list(ex.map(square, [1, 2, 3])) == [1, 4, 9]

